# ---------------------------------------------------------------------------
# changelog
# ---------------------------------------------------------------------------
text = CHANGELOG.read_text(encoding='utf-8')
entry = '''## 1.5.3\n\n- Correct D2 dual-lens addressing from native-UI packet captures and a known-good legacy snapshot client: D2 image controls and snapshots use channel 2; D3 uses channel 1.\n- Use D2's native `Image/Advanced/Private/Exposure/` endpoint for reliable Auto/Day/Night control.\n- Add D2 detailed smart-illumination controls discovered from native-UI traffic: White Light/Infrared type, separate white-light and infrared control-mode selects, white-light level, and infrared near/far levels.\n- Slow the diagnostic LampCtrl watcher to 5 seconds and include LAPI HTTP error response bodies in diagnostics.\n\n'''
if entry not in text:
    CHANGELOG.write_text(entry + text, encoding='utf-8')
